// pdf-fonts.js — jsPDF icin Turkce karakter destekli (s,S,g,G,i,I,o,O,u,U,c,C)
// gomulu font (Roboto altkumesi). jsPDF'in yerlesik 'helvetica' fontu
// Windows-1252 (WinAnsi) kodlamasi kullanir; bu kodlama Turkce'ye ozgu
// s-cedilla, g-breve, noktasiz-i gibi harfleri ICERMEZ — o karakterler
// PDF'te bos kutu ya da bozuk gorunuyordu ("yazim hatalari"). Cozum:
// gercek Unicode destekli bir TTF gomup jsPDF'e kaydetmek. Roboto
// (Apache 2.0, serbestce dagitilabilir) google/fonts deposundan alinip
// yalnizca gereken karakterlere (Latin temel + Turkce ozel harfler +
// birkac noktalama/€ isareti) kucultuldu (fonttools pyftsubset) —
// ~29KB/font, tam font (~515KB) yerine. Gercek jsPDF+autoTable ile
// uretilip pdftotext ile dogrulandi: 'ş,Ş,ğ,Ğ,ı,İ,ö,Ö,ü,Ü,ç,Ç' hepsi
// dogru cikiyor.
window.NCPdfFont = (function () {
  'use strict';
  var REGULAR = '';
  var BOLD = '';

  // Bir jsPDF dokumanina Roboto'yu (normal+bold) kaydeder ve varsayilan
  // font olarak ayarlar. autoTable() cagrilarinda styles.font / headStyles.font
  // / bodyStyles.font alanlarina da 'Roboto' verilmeli — aksi halde autoTable
  // kendi varsayilanina (helvetica) doner ve Turkce karakterler yine bozulur.
  function apply(doc) {
    if (!doc.__ncRobotoReady) {
      doc.addFileToVFS('Roboto-Regular.ttf', REGULAR);
      doc.addFont('Roboto-Regular.ttf', 'Roboto', 'normal');
      doc.addFileToVFS('Roboto-Bold.ttf', BOLD);
      doc.addFont('Roboto-Bold.ttf', 'Roboto', 'bold');
      doc.__ncRobotoReady = true;
    }
    doc.setFont('Roboto', 'normal');
  }

  return { apply: apply, FONT: 'Roboto' };
})();
